__NUXT_JSONP__("/por/stay", (function(a,b,c,d,e,f,g,h,i,j){return {data:[{details:{slug:"por",pageTitle:"Acomodações | Mentor Language Institute",pageDescription:"A MLI trabalha em parceria com a U.S. Support Services Inc., que fornece acomodação para os alunos da MLI.",title:"Acomodações",subtitle:["A MLI trabalha em parceria com a U.S. Support Services Inc., que fornece acomodação para os alunos da MLI.  \u003Cbr \u002F\u003EPara obter mais detalhes, visite  \u003Ca href=\"www.usssinc.net\u002Fpor\" target=\"_blank\"\u003Ewww.usssinc.net\u002Fpor\u003C\u002Fa\u003E"],image:"\u002Fimages\u002Flocation\u002Faccommodations\u002Faccommodation-1.jpg",gallery:["\u002Fimages\u002Flocation\u002Faccommodations\u002Faccommodation-2.jpg","\u002Fimages\u002Flocation\u002Faccommodations\u002Faccommodation-3.jpg"],note:"Os estudantes podem escolher homestay ou dormitório.",types:[{title:"Dormitório",description:["Existem 40 quartos no dormitório. Haverão muitas oportunidades para se comunicar com outros estudantes internacionais. Recomendamos que você fique em um dos nossos dormitórios se estiver com orçamento limitado."],lists:["\u003Cb\u003EQuarto\u003C\u002Fb\u003E  : Privado (individual), Compartilhado (2 pessoas) ou Quádruplo (4 pessoas)","\u003Cb\u003ERefeição\u003C\u002Fb\u003E  : sem refeições [está disponível uma cozinha totalmente equipada]","\u003Cb\u003EPrivacidade\u003C\u002Fb\u003E  : há mais privacidade nos dormitórios do que em uma casa de família, no entanto, existem algumas regras nos dormitórios.","\u003Cb\u003ECaminho para a escola\u003C\u002Fb\u003E  : cerca de 20 minutos a pé ou de ônibus."],gallery:["\u002Fimages\u002Flocation\u002Faccommodations\u002Fdormitory-1.jpg","\u002Fimages\u002Flocation\u002Faccommodations\u002Fdormitory-2.jpg","\u002Fimages\u002Flocation\u002Faccommodations\u002Fdormitory-3.jpg","\u002Fimages\u002Flocation\u002Faccommodations\u002Fdormitory-4.jpg"],prices:[{title:"Preços de dormitórios",table:{tableMaxCol:4,title:"Placement Fee* : $200\u003Cbr \u002F\u003E Se menor de 18 anos, o aluguel será aproximadamente 10% a mais do que o preço para uma pessoa com mais de 18 anos.",thead:[b,c,"Shared (2 people)","Quad (4 people)"],tbody:[[d,a,a,a],[e,"$550","$410",a],[f,"$1,100","$820","$600"],[g,"$1,650","$1,230","$900"],[h,"$2,200","$1,640","$1,200"],[i,"$4,160","$2,960","$2,160"],[j,"$6,240","$4,440","$3,240"]]},notes:["*Placement fee é um único pagamento. Não é reembolsável.\u003Cbr \u002F\u003E**Security deposit (calção) será reembolsável depois que o aluno sair da acomodação."]}]},{title:"Homestay",description:["Os alunos que escolhem morar com uma família de homestay estão à procura de um ambiente seguro, acolhedor, e atmosfera confortável onde eles podem praticar o inglês. É também uma oportunidade para aprender sobre os costumes, tradições e valores familiares americanos."],lists:["\u003Cb\u003ERoom\u003C\u002Fb\u003E : Private (Individual)","\u003Cb\u003EMeal\u003C\u002Fb\u003E : 2 meals a day (Breakfast and Dinner)","\u003Cb\u003EPrivacy\u003C\u002Fb\u003E : There are some house rules depending on the host family.","\u003Cb\u003ECommute\u003C\u002Fb\u003E : 30- 45 minutes by bus"],gallery:["\u002Fimages\u002Flocation\u002Faccommodations\u002Fhomestay-1.jpg","\u002Fimages\u002Flocation\u002Faccommodations\u002Fhomestay-2.jpg","\u002Fimages\u002Flocation\u002Faccommodations\u002Fhomestay-3.jpg","\u002Fimages\u002Flocation\u002Faccommodations\u002Fhomestay-4.jpg"],prices:[{title:"Preços de Homestay",table:{tableMaxCol:3,title:"Placement Fee* : $300\u003Cbr \u002F\u003E Se menor de 18 anos, o aluguel será aproximadamente 10% a mais do que o preço para uma pessoa com mais de 18 anos.",thead:[b,c,"Shared***"],tbody:[[d,a,a],[e,"$436","$384"],[f,"$872","$768"],[g,"$1,308","$1,152"],[h,"$1,744","$1,536"],[i,"$3,160","$2,904"],[j,"$4,740","$4,356"]]},notes:["*Placement fee é um único pagamento. Não é reembolsável.\u003Cbr \u002F\u003E**Security deposit (calção), será reembolsável depois que o aluno sair da acomodação.\u003Cbr \u002F\u003E***Se você solicitar um homestay quarto compartilhado, \u003Cspan class=\"rmarker\"\u003Evocê deve aplicar com outra pessoa\u003C\u002Fspan\u003E"]}]}],comments:{title:"Comentários da nossa equipe",description:["Não é fácil encontrar um lugar para ficar quando se chega pela primeira vez nos EUA, especialmente para estudantes internacionais que não têm um número de Seguro Social (SSN) e histórico de crédito.","A maioria dos lugares requerem um SSN e histórico de crédito para alugar um lugar. Portanto, recomendamos que você fique em nossas acomodações por pelo menos os primeiros dois meses.","※ Seu alojamento será fornecido pela U.S. Support Service Inc. ou outros agentes."]},dir:"\u002Fstay",path:"\u002Fstay\u002Fpor",extension:".json",createdAt:"2026-10-22T16:31:31.107Z",updatedAt:"2025-05-26T12:06:27.920Z"}}],fetch:{},mutations:void 0}}("$300","","Private (Individual)","\u003Cb\u003EDeposit\u003C\u002Fb\u003E","1 week","2 weeks","3 weeks","4 weeks","8 weeks","12 weeks")));